def adressen_umziehen(apps, schema_editor):
    """Aus jeder Kundenzeile wird eine Standardadresse und ein Kontaktweg.

    **Genau so, wie ``Kunde.anlegen`` es tut**, nur hier von Hand, weil
    eine Migration die Modellmethoden nicht benutzen darf: ``apps.get_model``
    liefert ein historisches Modell ohne ``save()``, ohne ``clean()`` und
    ohne Eigenschaften. Was diese Funktion schreibt, muss deshalb schon
    vollständig sein.

    Was leer war, wird nicht angelegt. Ein Kunde ohne Straße und ohne Ort
    bekommt keine Adresszeile, die nur einen Ländercode trägt; er bekommt
    keine Adresse, und das ist die richtige Aussage über ihn.

    ``ist_standard=True`` an allem, was hier entsteht: Vor dieser Migration
    gab es je Kunde genau eine Anschrift und genau eine E-Mail-Adresse.
    Beide sind damit unstrittig die Standardwerte.
    """
    Kunde = apps.get_model('faktura', 'Kunde')
    Adresse = apps.get_model('faktura', 'Adresse')
    Kontaktweg = apps.get_model('faktura', 'Kontaktweg')

    adressen = []
    kontakte = []
    for kunde in Kunde.objects.all().iterator():
        if kunde.strasse or kunde.plz or kunde.ort:
            adressen.append(Adresse(
                kunde_id=kunde.pk,
                verwendung='rechnung',
                zusatz='',
                strasse=kunde.strasse,
                plz=kunde.plz,
                ort=kunde.ort,
                land=kunde.land or 'DE',
                ist_standard=True,
            ))
        if kunde.email:
            kontakte.append(Kontaktweg(
                kunde_id=kunde.pk,
                art='email',
                wert=kunde.email,
                bezeichnung='',
                ist_standard=True,
            ))

    Adresse.objects.bulk_create(adressen, batch_size=500)
    Kontaktweg.objects.bulk_create(kontakte, batch_size=500)


def adressen_zurueck(apps, schema_editor):
    """Schreibt die Standardadresse in die wiederhergestellten Spalten zurück.

    **Damit die Migration rückwärts läuft und nicht nur vorwärts.** Django
    stellt die fünf Spalten beim Zurückrollen leer wieder her; ohne diese
    Funktion stünde danach ein Kundenstamm ohne Anschriften da, derselbe
    stille Verlust, nur in die andere Richtung.

    Was über die Standardadresse hinausging (zweite Anschriften, weitere
    E-Mail-Adressen, Ansprechpartner), geht dabei verloren. Das ist keine
    Nachlässigkeit, sondern die Natur des Rückwegs: In eine Spalte passt
    eine Zeile.
    """
    Kunde = apps.get_model('faktura', 'Kunde')
    Adresse = apps.get_model('faktura', 'Adresse')
    Kontaktweg = apps.get_model('faktura', 'Kontaktweg')

    for adresse in Adresse.objects.filter(ist_standard=True).iterator():
        Kunde.objects.filter(pk=adresse.kunde_id).update(
            strasse=adresse.strasse, plz=adresse.plz,
            ort=adresse.ort, land=adresse.land)
    for kontakt in (Kontaktweg.objects
                    .filter(art='email', ist_standard=True,
                            kunde__isnull=False).iterator()):
        Kunde.objects.filter(pk=kontakt.kunde_id).update(email=kontakt.wert)


